mapper.select:
SELECT *
FROM rum_daily_topn as r


        AND r.env = #{query.env}


        AND r.metric = #{query.metric}


        AND r.route_key = #{query.routeKey}


        AND r.release_ver = #{query.releaseVer}


        AND r.day >= #{query.startDate}


        AND r.day <= #{query.endDate}


        AND r.kind = #{query.kind}


order by r.day
